mapper.select:
/* 반려동물 행 잠금 */
SELECT PET_SN
  FROM PET
 WHERE PET_SN = #{petSn}
   AND DEL_YN = 'N'
   FOR UPDATE

/* 반려동물 기본 케어 항목 수 */
SELECT COUNT(*)
  FROM CARE_ARTCL
 WHERE PET_SN = #{petSn}
   AND BSC_ARTCL_YN = 'Y'
   AND DEL_YN = 'N'

/* 반려동물 케어 항목 중 요청 목록에 든 항목 수 */
SELECT COUNT(*)
  FROM CARE_ARTCL
 WHERE PET_SN = #{petSn}
   AND DEL_YN = 'N'
   AND CARE_ARTCL_SN IN

       #{careArtclSn}

/* 여러 반려동물의 케어 항목명 조회 */ SELECT CARE_ARTCL_SN , PET_SN , CARE_ARTCL_NM FROM CARE_ARTCL WHERE DEL_YN = 'N' AND PET_SN IN
#{petSn}
ORDER BY PET_SN , CARE_ARTCL_SN

mapper.insert:
/* 케어 항목 등록 */
INSERT INTO CARE_ARTCL
     ( PRSC_SN
     , REPT_PRVNT_MNG_SN
     , PET_SN
     , CARE_ZONE_CD
     , CARE_CYCLE_CD
     , CYCLE_DRCT_INPT_DAY_CNT
     , CARE_ARTCL_NM
     , RPRS_ICON_ID
     , NXTM_PRNMNT_YMD
     , LAST_CMPTN_YMD
     , MAIN_EXPSR_YN
     , MAIN_SORT_SEQ
     , BSC_ARTCL_YN
     , DEL_YN
     , REG_DT
     , MDFCN_DT
     , RGTR_ID
     , MDFR_ID )
VALUES
     ( #{prscSn}
     , #{reptPrvntMngSn}
     , #{petSn}
     , #{careZoneCd}
     , #{careCycleCd}
     , #{cycleDrctInptDayCnt}
     , #{careArtclNm}
     , #{rprsIconId}
     , #{nxtmPrnmntYmd}
     , #{lastCmptnYmd}
     , #{mainExpsrYn}
     , #{mainSortSeq}
     , #{bscArtclYn}
     , 'N'
     , NOW()
     , NOW()
     , #{rgtrId}
     , #{mdfrId} )

mapper.update:
/* 케어 항목 수정 */
UPDATE CARE_ARTCL
   SET CARE_ZONE_CD            = #{item.careZoneCd}
     , CARE_CYCLE_CD           = #{item.careCycleCd}
     , CYCLE_DRCT_INPT_DAY_CNT = #{item.cycleDrctInptDayCnt}
     , CARE_ARTCL_NM           = #{item.careArtclNm}
     , RPRS_ICON_ID            = #{item.rprsIconId}
     , NXTM_PRNMNT_YMD         = #{item.nxtmPrnmntYmd}
     , LAST_CMPTN_YMD          = #{item.lastCmptnYmd}
     , MDFR_ID                 = #{actorId}
     , MDFCN_DT                = NOW()
 WHERE CARE_ARTCL_SN = #{item.careArtclSn}
   AND DEL_YN = 'N'

/* 케어 항목 삭제 */
UPDATE CARE_ARTCL
   SET DEL_YN        = 'Y'
     , MAIN_EXPSR_YN = 'N'
     , MAIN_SORT_SEQ = 0
     , MDFR_ID       = #{actorId}
     , MDFCN_DT      = NOW()
 WHERE CARE_ARTCL_SN = #{careArtclSn}
   AND DEL_YN = 'N'

/* 반려동물 메인 표시 전체 해제 */
UPDATE CARE_ARTCL
   SET MAIN_EXPSR_YN = 'N'
     , MAIN_SORT_SEQ = 0
     , MDFR_ID       = #{actorId}
     , MDFCN_DT      = NOW()
 WHERE PET_SN = #{petSn}
   AND DEL_YN = 'N'
   AND MAIN_EXPSR_YN = 'Y'

/* 케어 항목 메인 표시 지정 */
UPDATE CARE_ARTCL
   SET MAIN_EXPSR_YN = 'Y'
     , MAIN_SORT_SEQ = #{mainSortSeq}
     , MDFR_ID       = #{actorId}
     , MDFCN_DT      = NOW()
 WHERE CARE_ARTCL_SN = #{careArtclSn}
   AND DEL_YN = 'N'

mapper.select:
/* 케어 완료 기록 목록 조회 */ SELECT H.CARE_CMPTN_HSTRY_SN , H.CARE_ARTCL_SN , A.CARE_ARTCL_NM , A.RPRS_ICON_ID , H.CMPTN_YMD , H.CMPTN_CYCL FROM CARE_CMPTN_HSTRY H JOIN CARE_ARTCL A ON A.CARE_ARTCL_SN = H.CARE_ARTCL_SN AND A.DEL_YN = 'N' LEFT JOIN PRSC P ON P.PRSC_SN = A.PRSC_SN AND P.DEL_YN = 'N' WHERE A.PET_SN = #{petSn} AND H.DEL_YN = 'N' AND H.CMPTN_CYCL >= COALESCE(P.DAY_MDCN_NMTM, 1)
AND H.CARE_ARTCL_SN = #{cond.careArtclSn}
AND H.CMPTN_YMD >= #{cond.fromYmd}
AND H.CMPTN_YMD <= #{cond.toYmd}
ORDER BY H.CMPTN_YMD DESC , H.CARE_CMPTN_HSTRY_SN DESC

/* 항목의 가장 최근 완료일, 잠금 읽기로 다른 트랜잭션의 최신 기록까지 반영 */
SELECT MAX(CMPTN_YMD)
  FROM CARE_CMPTN_HSTRY
 WHERE CARE_ARTCL_SN = #{careArtclSn}
   AND DEL_YN = 'N'
   FOR UPDATE

mapper.update:
/* 케어 완료 회차 수정 */
UPDATE CARE_CMPTN_HSTRY
   SET CMPTN_CYCL = #{cmptnCycl}
     , MDFR_ID    = #{actorId}
     , MDFCN_DT   = NOW()
 WHERE CARE_CMPTN_HSTRY_SN = #{careCmptnHstrySn}
   AND DEL_YN = 'N'

/* 케어 완료 기록 삭제 */
UPDATE CARE_CMPTN_HSTRY
   SET DEL_YN   = 'Y'
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE CARE_CMPTN_HSTRY_SN = #{careCmptnHstrySn}
   AND DEL_YN = 'N'

mapper.select:
/* 처방약 1일 복용 횟수 */
SELECT DAY_MDCN_NMTM
  FROM PRSC
 WHERE PRSC_SN = #{prscSn}
   AND DEL_YN = 'N'

/* 처방약 연동 투약 항목 존재 여부 */
SELECT EXISTS (
       SELECT 1
         FROM CARE_ARTCL
        WHERE PRSC_SN = #{prscSn}
          AND DEL_YN = 'N'
       )

mapper.update:
/* 처방약 연동 투약 항목 삭제(완료 기록은 유지) */
UPDATE CARE_ARTCL
   SET DEL_YN        = 'Y'
     , MAIN_EXPSR_YN = 'N'
     , MAIN_SORT_SEQ = 0
     , MDFR_ID       = #{actorId}
     , MDFCN_DT      = NOW()
 WHERE PRSC_SN = #{prscSn}
   AND DEL_YN = 'N'

/* 반복 예방 연동 케어 항목 삭제(완료 기록은 유지) */
UPDATE CARE_ARTCL
   SET DEL_YN        = 'Y'
     , MAIN_EXPSR_YN = 'N'
     , MAIN_SORT_SEQ = 0
     , MDFR_ID       = #{actorId}
     , MDFCN_DT      = NOW()
 WHERE REPT_PRVNT_MNG_SN = #{reptPrvntMngSn}
   AND DEL_YN = 'N'

mapper.select:
/* 반복 예방 시작일 */
SELECT BGNG_YMD
  FROM REPT_PRVNT_MNG
 WHERE REPT_PRVNT_MNG_SN = #{reptPrvntMngSn}
   AND DEL_YN = 'N'
